export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerOptions {
  failureThreshold?: number;
  resetTimeoutMs?: number;
}

export class CircuitBreaker {
  private currentState: CircuitState = 'CLOSED';
  private failureCount: number = 0;
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;
  private nextAttemptTimestamp: number = 0;

  constructor(options?: CircuitBreakerOptions) {
    this.failureThreshold = options?.failureThreshold ?? 5;
    this.resetTimeoutMs = options?.resetTimeoutMs ?? 10000;
  }

  public get state(): CircuitState {
    return this.getState();
  }

  public getState(): CircuitState {
    if (this.currentState === 'OPEN' && Date.now() >= this.nextAttemptTimestamp) {
      this.currentState = 'HALF_OPEN';
    }
    return this.currentState;
  }

  public recordSuccess(): void {
    this.failureCount = 0;
    this.currentState = 'CLOSED';
  }

  public recordFailure(): void {
    this.failureCount += 1;
    if (this.currentState === 'HALF_OPEN' || this.failureCount >= this.failureThreshold) {
      this.currentState = 'OPEN';
      this.nextAttemptTimestamp = Date.now() + this.resetTimeoutMs;
    }
  }

  public async execute<T>(action: () => Promise<T>): Promise<T> {
    const currentState = this.getState();

    if (currentState === 'OPEN') {
      throw new Error(
        `Circuit breaker is OPEN. Next attempt allowed after ${new Date(this.nextAttemptTimestamp).toISOString()}`
      );
    }

    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }
}

export class ApiError extends Error {
  public readonly statusCode: number;

  constructor(message: string, statusCode: number) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
    Object.setPrototypeOf(this, ApiError.prototype);
  }
}

export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class ResilientHttpClient {
  private readonly circuitBreaker: CircuitBreaker;

  constructor(circuitBreaker?: CircuitBreaker) {
    this.circuitBreaker = circuitBreaker ?? new CircuitBreaker();
  }

  public async get<T>(url: string, options?: RequestOptions): Promise<T> {
    return this.circuitBreaker.execute(async () => {
      const controller = new AbortController();
      const timeoutMs = options?.timeoutMs ?? 5000;
      let timeoutTriggered = false;

      const timeoutHandle = setTimeout(() => {
        timeoutTriggered = true;
        controller.abort();
      }, timeoutMs);

      try {
        const response = await fetch(url, {
          method: 'GET',
          headers: {
            Accept: 'application/json',
            ...(options?.headers ?? {}),
          },
          signal: controller.signal,
        });

        if (!response.ok) {
          let errorMessage: string;
          try {
            const errorBody = await response.text();
            errorMessage = errorBody.length > 0 ? errorBody : response.statusText;
          } catch {
            errorMessage = response.statusText;
          }
          throw new ApiError(errorMessage || `HTTP ${response.status}`, response.status);
        }

        const contentType = response.headers.get('content-type');
        if (contentType && contentType.includes('application/json')) {
          return (await response.json()) as T;
        }

        const textData = await response.text();
        try {
          return JSON.parse(textData) as T;
        } catch {
          return textData as unknown as T;
        }
      } catch (error) {
        if (timeoutTriggered) {
          throw new ApiError(`Request timeout after ${timeoutMs}ms`, 408);
        }
        if (error instanceof ApiError) {
          throw error;
        }
        const message = error instanceof Error ? error.message : 'Network request failed';
        throw new ApiError(message, 500);
      } finally {
        clearTimeout(timeoutHandle);
      }
    });
  }
}
